/**
 * Cloudflare Worker entry: the OpenNext app, its Cron Triggers, and the
 * webhook queue consumer.
 *
 * Inbound Meta events are stored in `webhook_events` by /api/webhooks/meta,
 * which then sends a signal to WEBHOOK_QUEUE. The consumer below drains the
 * table right away (seconds instead of up to a minute). The minute cron stays
 * as a safety net, so nothing is lost if the queue is missing or a send fails.
 */
// @ts-ignore — generated by `opennextjs-cloudflare build`
import app from "../.open-next/worker.js";

type Env = { CRON_SECRET?: string; APP_URL?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };
type MessageBatch = { messages: unknown[]; ackAll(): void; retryAll(): void };

const CRON_ROUTES: Record<string, string> = {
  "* * * * *": "/api/worker/drain", // safety net for the inbound queue — every minute
  "0 * * * *": "/api/worker/jobs",  // scheduled jobs — hourly
};

/** Call one of the app's protected worker routes in-process. */
async function callRoute(path: string, env: Env, ctx: Ctx): Promise<Response> {
  const base = env.APP_URL ?? "https://leadra.internal";
  const req = new Request(new URL(path, base), {
    headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
  });
  const res: Response = await app.fetch(req, env, ctx);
  if (!res.ok) console.error("worker_route_failed", path, res.status, (await res.clone().text()).slice(0, 200));
  return res;
}

export default {
  fetch: app.fetch,

  async scheduled(event: { cron: string }, env: Env, ctx: Ctx) {
    const path = CRON_ROUTES[event.cron];
    if (path) ctx.waitUntil(callRoute(path, env, ctx));
  },

  // Each message is only a "new events stored" signal, so one drain covers the batch.
  async queue(batch: MessageBatch, env: Env, ctx: Ctx) {
    const res = await callRoute("/api/worker/drain", env, ctx);
    if (res.ok) batch.ackAll();
    else batch.retryAll();
  },
};
